#[cfg(test)]
mod tests {
    /// The enums defined outside this file accept every value of their schema.
    #[test]
    fn external_enums_accept_the_schema_values() {
        // DatasetManifest.venue
        for v in ["generic", "nasdaq", "cme", "coinbase"] {
            let r = serde_json::from_value::<qt_types::Venue>(serde_json::json!(v));
            assert!(r.is_ok(), "DatasetManifest.venue: {v}");
        }
        // DatasetManifest.validation_status
        for v in ["real_data", "synthetic_only", "assumed", "fixture_only"] {
            let r = serde_json::from_value::<qt_types::ValidationStatus>(serde_json::json!(v));
            assert!(r.is_ok(), "DatasetManifest.validation_status: {v}");
        }
        // DatasetManifest.rule_set
        for v in ["generic", "nasdaq", "cme", "coinbase", "crypto_l3", "iex", "nyse"] {
            let r = serde_json::from_value::<qt_types::RuleSet>(serde_json::json!(v));
            assert!(r.is_ok(), "DatasetManifest.rule_set: {v}");
        }
        // DataSource.validation_status
        for v in ["real_data", "synthetic_only", "assumed", "fixture_only"] {
            let r = serde_json::from_value::<qt_types::ValidationStatus>(serde_json::json!(v));
            assert!(r.is_ok(), "DataSource.validation_status: {v}");
        }
        // WhyTrace.side
        for v in ["B", "A", "N"] {
            let r = serde_json::from_value::<String>(serde_json::json!(v));
            assert!(r.is_ok(), "WhyTrace.side: {v}");
        }
        // WhyEvent.action
        for v in ["A", "C", "M", "R", "T", "F", "N"] {
            let r = serde_json::from_value::<String>(serde_json::json!(v));
            assert!(r.is_ok(), "WhyEvent.action: {v}");
        }
        // WhyEvent.side
        for v in ["B", "A", "N"] {
            let r = serde_json::from_value::<String>(serde_json::json!(v));
            assert!(r.is_ok(), "WhyEvent.side: {v}");
        }
    }
}
